using System.Text;
using System.Text.Json;

namespace NightCodeForge.Core.Domain;

/// <summary>
/// Utility for auto-repairing common malformed or truncated JSON payloads generated by LLM tool calls
/// (e.g. missing closing brackets/braces, unescaped newlines, trailing commas).
/// </summary>
public static class JsonRepairHelper
{
    /// <summary>
    /// Attempts to repair malformed JSON (such as missing closing ']' or '}', unclosed strings, trailing commas, or unescaped newlines).
    /// If the repaired string is valid JSON, returns it; otherwise returns the original trimmed string.
    /// </summary>
    public static string Repair(string? raw)
    {
        if (string.IsNullOrWhiteSpace(raw))
        {
            return "{}";
        }

        var clean = raw.Trim();

        // Strip markdown code fences (```json ... ``` or ``` ...)
        if (clean.StartsWith("```"))
        {
            clean = StripMarkdownFences(clean);
        }

        // Try direct parse first
        try
        {
            using var doc = JsonDocument.Parse(clean);
            return clean;
        }
        catch (JsonException)
        {
            // Proceed to repair
        }

        var sb = new StringBuilder();
        bool inString = false;
        bool isEscaped = false;
        var stack = new Stack<char>();

        for (int i = 0; i < clean.Length; i++)
        {
            char c = clean[i];

            if (c == '\\' && inString)
            {
                isEscaped = !isEscaped;
                sb.Append(c);
                continue;
            }

            if (c == '"' && !isEscaped)
            {
                inString = !inString;
                sb.Append(c);
                continue;
            }

            if (inString)
            {
                if (c == '\r' || c == '\n')
                {
                    if (c == '\r' && i + 1 < clean.Length && clean[i + 1] == '\n')
                    {
                        i++;
                    }
                    sb.Append("\\n");
                }
                else if (c == '\t')
                {
                    sb.Append("\\t");
                }
                else
                {
                    sb.Append(c);
                }
                isEscaped = false;
                continue;
            }

            isEscaped = false;

            if (c == '[')
            {
                stack.Push(']');
                sb.Append(c);
            }
            else if (c == '{')
            {
                stack.Push('}');
                sb.Append(c);
            }
            else if (c == ']' || c == '}')
            {
                if (stack.Count > 0 && stack.Peek() == c)
                {
                    PrepareContainerClose(sb, c);
                    stack.Pop();
                    sb.Append(c);
                }
                else if (stack.Count > 0 && stack.Contains(c))
                {
                    // An inner container was left unclosed before this outer delimiter
                    while (stack.Count > 0 && stack.Peek() != c)
                    {
                        var innerClose = stack.Pop();
                        PrepareContainerClose(sb, innerClose);
                        sb.Append(innerClose);
                    }
                    if (stack.Count > 0)
                    {
                        PrepareContainerClose(sb, c);
                        stack.Pop();
                    }
                    sb.Append(c);
                }
                // Otherwise, c is an unmatched excess closing delimiter; skip it
            }
            else
            {
                sb.Append(c);
            }
        }

        // If string was left open, close it
        if (inString)
        {
            if (isEscaped)
            {
                sb.Append('\\');
            }
            sb.Append('"');
        }

        // Remove trailing commas before closing
        TrimTrailingCommas(sb);

        // Append any unclosed brackets/braces in reverse order
        while (stack.Count > 0)
        {
            var closeChar = stack.Pop();
            PrepareContainerClose(sb, closeChar);
            sb.Append(closeChar);
        }

        var result = sb.ToString();

        // Verify if repaired string parses
        try
        {
            using var doc = JsonDocument.Parse(result);
            return result;
        }
        catch (JsonException)
        {
            return clean;
        }
    }

    private static void PrepareContainerClose(StringBuilder sb, char closeChar)
    {
        TrimTrailingCommas(sb);
        if (closeChar != '}')
        {
            return;
        }

        int idx = sb.Length - 1;
        while (idx >= 0 && char.IsWhiteSpace(sb[idx]))
        {
            idx--;
        }

        if (idx < 0)
        {
            return;
        }

        if (sb[idx] == ':')
        {
            int quoteEnd = idx - 1;
            while (quoteEnd >= 0 && char.IsWhiteSpace(sb[quoteEnd]))
            {
                quoteEnd--;
            }

            if (quoteEnd >= 0 && sb[quoteEnd] == '"')
            {
                int quoteStart = FindMatchingOpeningQuote(sb, quoteEnd);
                if (quoteStart >= 0)
                {
                    int beforeKey = quoteStart - 1;
                    while (beforeKey >= 0 && char.IsWhiteSpace(sb[beforeKey]))
                    {
                        beforeKey--;
                    }

                    if (beforeKey >= 0 && sb[beforeKey] == ',')
                    {
                        sb.Length = beforeKey;
                        TrimTrailingCommas(sb);
                        return;
                    }

                    if (beforeKey >= 0 && sb[beforeKey] == '{')
                    {
                        sb.Length = beforeKey + 1;
                        return;
                    }
                }
            }

            sb.Append("null");
            return;
        }

        if (sb[idx] == '"')
        {
            int quoteStart = FindMatchingOpeningQuote(sb, idx);
            if (quoteStart >= 0)
            {
                int beforeKey = quoteStart - 1;
                while (beforeKey >= 0 && char.IsWhiteSpace(sb[beforeKey]))
                {
                    beforeKey--;
                }

                if (beforeKey >= 0 && sb[beforeKey] == ',')
                {
                    sb.Length = beforeKey;
                    TrimTrailingCommas(sb);
                }
                else if (beforeKey >= 0 && sb[beforeKey] == '{')
                {
                    sb.Length = beforeKey + 1;
                }
            }
        }
    }

    private static int FindMatchingOpeningQuote(StringBuilder sb, int closingQuoteIndex)
    {
        for (int i = closingQuoteIndex - 1; i >= 0; i--)
        {
            if (sb[i] != '"')
            {
                continue;
            }

            int backslashes = 0;
            for (int j = i - 1; j >= 0 && sb[j] == '\\'; j--)
            {
                backslashes++;
            }

            if (backslashes % 2 == 0)
            {
                return i;
            }
        }

        return -1;
    }

    private static void TrimTrailingCommas(StringBuilder sb)
    {
        while (sb.Length > 0)
        {
            int idx = sb.Length - 1;
            while (idx >= 0 && char.IsWhiteSpace(sb[idx]))
            {
                idx--;
            }

            if (idx >= 0 && sb[idx] == ',')
            {
                sb.Length = idx;
            }
            else
            {
                break;
            }
        }
    }

    private static string StripMarkdownFences(string input)
    {
        var trimmedInput = input.Trim();
        if (!trimmedInput.StartsWith("```", StringComparison.Ordinal))
        {
            return trimmedInput;
        }

        // Remove opening ```[lang]
        int afterTicks = 3;
        while (afterTicks < trimmedInput.Length && (char.IsLetterOrDigit(trimmedInput[afterTicks]) || trimmedInput[afterTicks] == '_' || trimmedInput[afterTicks] == '-'))
        {
            afterTicks++;
        }

        var body = trimmedInput.Substring(afterTicks).Trim();
        if (body.EndsWith("```", StringComparison.Ordinal))
        {
            body = body.Substring(0, body.Length - 3).Trim();
        }

        return string.IsNullOrWhiteSpace(body) ? trimmedInput : body;
    }
}

